"""Render the full-set report from saved, auditable app events."""
from pathlib import Path
import json
P=Path(__file__).resolve().parents[1]/'evaluation/coach_c/mobile_live_20261012'
def main():
 data=json.loads((P/'results.json').read_text());s=data['summary'];rows=data['clips']
 assert s['replay_complete']==30, 'Wait for all source replays before publishing the report.'
 out=['# Coach C: 30 clips through the live Android pipeline', '', 'Date: 12 October 2026. Device: Xiaomi 23021RAAEG. Original five-fold GRU; CPU pose; pose priority enabled. All 30 source files and original model weights verified by SHA-256. One replay per clip; no tuning during this run.', '', '## Findings', '', '| Measure | Result |', '|---|---:|', f"| Completed source replays | {s['replay_complete']}/30 |",f"| Clips with completed displayed feedback (including notices) | {s['clips_with_output']}/30 |", f"| Substantive coaching outputs | {s['substantive_feedback']}/30 |", f"| Frozen Session 2 substantive outputs | {s['frozen_substantive']}/30 |", f"| Any GRU classification, including low confidence | {s['classification_available']}/30 |",f"| Classifications meeting 0.60 confidence | {s['confident_classifications']}/30 |",f"| Recording-category agreement among confident classifications | {s['confident_category_agreements']}/{s['confident_classifications']} |", f"| Available paddle measurements | {s['paddle_available']}/30 |", f"| Exact full feedback-text matches to frozen output | {s['exact_feedback_matches']}/30 |",f"| Median / maximum detected-end to UI assignment | {s['gate_to_ui_median_ms']} / {s['gate_to_ui_max_ms']} ms |",f"| Results before source-file end | {s['before_source_end']} |",f"| Results 0-2 seconds after source-file end | {s['within_0_to_2s_after_source_end']} |",f"| Results more than 2 seconds after source-file end | {s['over_2s_after_source_end']} |", '', '| Final phone status | Clips |', '|---|---:|']
 for name,count in s['status_counts'].items(): out.append(f'| {name} | {count} |')
 insufficient=[r for r in rows if r['status']=='INSUFFICIENT_DATA'];frames=[r['frames'] for r in insufficient if r['frames'] is not None]
 out += ['', '## Interpretation', '', f"The app produced substantive coaching on {s['substantive_feedback']} of 30 clips, versus 21 frozen outputs previously prepared for Coach C. This measures coverage, not coaching correctness. The frozen desktop and live phone paths differ in several stages, so this comparison does not isolate a single cause.", '', f"Insufficient-data results numbered {len(insufficient)}; their usable real-pose counts were {min(frames) if frames else 'N/A'} to {max(frames) if frames else 'N/A'}. The app requires 32 real poses before classification. Missing classification can therefore happen before the original GRU has an opportunity to evaluate a serve. A completed source replay is not proof of a completed motion-gated capture.", '', 'Recording-category agreement is not independent Coach C classification accuracy. A CORRECTIVE/POSITIVE status is not proof that its advice is valid. Coach C evaluated the frozen messages, not these new live-app outputs; his ratings cannot be transferred to this run.', '', 'Low detected-end latency does not establish a successful two-second coaching result. No-output cases remain failures of availability; source-file end is not an independently marked physical serve endpoint. This replay excludes decoding and camera acquisition, and measures UI text assignment rather than externally observed rendered pixels. Single-pass results do not establish repeatability.', '', '## Suggested next work', '', '1. **Compare exact phone and desktop inputs.** Capture pose timestamps and tensors, then run identical tensors through both classifiers. Isolate pose extraction, capture boundaries and normalization before retraining.', '2. **Test explicit start/finish capture.** Compare a recording button or bounded window against automatic gating, retaining setup and follow-through. This may fix missed boundaries, but does not itself fix low pose throughput.', '3. **Recover pose and paddle evidence.** Evaluate GPU or scheduling changes on quality as well as speed. Do not lower evidence/confidence requirements just to display more advice. MediaPipe live-stream mode can ignore incoming frames while busy; nominal camera FPS is not usable pose FPS. [Official documentation](https://ai.google.dev/edge/mediapipe/solutions/vision/pose_landmarker/python).', '4. **Validate on fresh recordings after tuning.** These 30 clips are now mobile diagnostics. Keep the finished Coach C study separate; train on participant-separated phone data and independently judge any changed coaching outputs.', '', '## Per-clip results', '', '| Clip | Recording category | Phone prediction | Real poses | Phone status | Frozen status | Detected-end to UI ms |', '|---|---|---|---:|---|---|---:|']
 for r in rows: out.append(f"| {r['clip']} | {r['recording_category']} | {r['prediction'] or 'Unavailable'} | {r['frames']} | {r['status']} | {r['frozen_status']} | {r['gate_to_ui_ms']} |")
 out += ['', 'See [protocol](PROTOCOL.md), [per-clip CSV](clip_results.csv), [all event records](results.json) and [APK/source identities](protocol.json). Raw logs are in logs/. Summary uses the final completed displayed result per clip; all event records are preserved.', '', '## Exact displayed phone feedback', '']
 for r in rows: out += [f"### {r['clip']} - {r['status']}", '', r['feedback'] or '(No completed feedback was displayed during the replay observation window.)', '']
 (P/'REPORT.md').write_text('\n'.join(out),encoding='utf-8')
 print('Saved '+str(P/'REPORT.md'))
if __name__=='__main__': main()
